"任何房间：主基地耐久 +{0}%。契合「防御」：守城时 {1} 名陶土守卫加入战斗。": "Всяка стая: здравина на Цитаделата +{0}%. В стая „Защита“: в отбраната участват глинени стражи: {1}.",
"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Всяка стая: в поход може да се носят повече реликви: +{0}. В стая „Защита“: оръжията нанасят +{1}% щети, удрят по площ и забавят; останалите — още стражи: {2}.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Всяка стая: запаси от походи +{0}%. В стая „Съдба“: запаси още +{1}%, начален множител на точките във всяка битка +{2}.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Всяка стая: видимост в похода +{0}, начален множител на точките +{1}. В стая „Съдба / Специално“: картата на похода е изцяло открита от началото, множител още +{2}.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Всяка стая: атака на отрядите в похода +{0}%. В стая „Тренировка“: опит на лидера от походи +{1}%.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Всяка стая: здраве на отрядите в похода +{0}%. В стая „Медицина“: лечение в болницата +{1}%, лидерът се лекува с още {2}% на ден.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Всяка стая: шанс за чертежи +{0}%. В стая „Фантастика“: базата получава отломки от души +{1} на ден.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Всяка стая: шанс за чертежи +{0}%. В стая „Коване“: {1}% шанс при коване да получиш още една.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Всяка стая: базата получава отломки от души +{0} на ден. В стая „Магия“: още +{1} на ден.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Всяка стая: базата получава запаси +{0} на ден. В стая „Снабдяване“: собствен ефект на тази стая ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Всяка стая: базата получава запаси +{0} на ден, опит на лидера +{1} на ден. В стая „Снабдяване / Природа“: собствен ефект на тази стая ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Всяка стая: цена на коването на реликви -{0}%. В стая „Коване / Оръжие“: коване — {1}% шанс за качество +{2}; оръжие — щети +{3}%.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Всяка стая: строежът е два пъти по-бърз, при завършване се връщат {0}% от запасите. В стая „Чудо“: връщат се до {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Всяка стая: щети на всички отбранителни кули +{0}%. В стая „Оръжие“: обхват +{1}, скорост на атака +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Всяка стая: цена на разкопаването -{0}%. В стая „Специално“: всеки строеж е с {1} дн. по-кратък.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Всяка стая: начален множител на точките във всяка битка +{0}. В стая „Коване“: качеството на изкованите реликви винаги е +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Всяка стая: презареждане на умението на лидера −{0} ет. В стая „Съдба“: в началото на похода повече предмети за поддръжка: +{1} (ефект поне „Епичен“).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Всяка стая: атака на лидера +{0}%. В стая „Оръжие“: щети +{1}%, всяка атака пуска верижна мълния (скокове: {2}).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Всяка стая: лидерът възстановява {0}% здраве на ден (без болница). В стая „Медицина / Вода“: лечение в болницата +{1}%; обхват на водните оръжия +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Всяка стая: опит на лидера +{0} на ден. В стая „Производство“: собствена продукция на тази стая ×{1}.",
