"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Напред е „Операционната“: главният лекар казва, че операцията е минала успешно — пациентът просто още не се е събудил.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Напред е „Морското дъно“: под пристанището има още един град и портата му е паст.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Напред е „Дървото на познанието“: то помни всичко, което се е случвало в гората, и не иска да помни нищо повече.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "Напред е „Кралицата на елфите“: тя е чакала край лунното езеро триста години. Казва, че е чакала именно теб.",
